    <section v-if="section==='contact'" class="its-section its-wrap"><ItscoSupportForm/></section>
    <section v-if="section==='resources'" class="its-section its-wrap"><div class="its-three"><article v-for="[title,body,href] in resources" :key="title" class="its-card"><h2>{{title}}</h2><p>{{body}}</p><router-link class="its-button its-outline" :to="href">Get started →</router-link></article></div></section>

