   </template>
  </main>
  <footer class="its-footer"><div class="its-wrap"><div class="its-footer-top"><router-link to="/p/itsco"><img :src="asset('logo.png')" alt="ITSCO — In The School Counselors"/></router-link><nav aria-label="Explore ITSCO"><router-link v-for="[label,slug] in [...nav,['Explore our growth','growth'],['Our impact','impact'],['Our team','team'],['Insurance','insurance']]" :key="slug" :to="path(slug)">{{label}}</router-link></nav><nav aria-label="Quick links"><router-link to="/itsco/login">Client portal</router-link><router-link to="/careers/itsco">Careers / join our team</router-link><router-link to="/join/itsco/counseling">Start enrollment</router-link><router-link to="/itsco/school-referral">School referrals</router-link></nav><p class="its-handwritten">People.<br/>Purpose.<br/>Stronger communities.</p></div><div class="its-footer-bottom"><small>© {{new Date().getFullYear()}} ITSCO. All rights reserved.</small><nav aria-label="Policies"><router-link to="/itsco/privacypolicy">Privacy</router-link><router-link to="/itsco/terms">Terms</router-link><router-link :to="path('contact')">Accessibility help</router-link></nav></div></div></footer>
  <router-link v-if="section!=='contact'" class="its-support-launcher" :to="path('contact')"><Icon name="chat"/>Message our team</router-link>
 </div>
</template>
<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';
import {useRoute} from 'vue-router';
import api from '../../services/api';
import Icon from '../../components/rise/RiseIcon.vue';
import ItscoProviderDirectory from '../../components/itsco/ItscoProviderDirectory.vue';
import ItscoSchoolPartners from '../../components/itsco/ItscoSchoolPartners.vue';
import ItscoSupportForm from '../../components/itsco/ItscoSupportForm.vue';
import PublicProviderProfileEditor from '../../components/publicServices/PublicProviderProfileEditor.vue';
import {publicWebsiteUrl as safe} from '../../composables/useStandalonePublicWebsite';
const route=useRoute(),data=ref(null),loading=ref(true),error=ref(''),menu=ref(false),department=ref(''),offset=ref(0),rotationEnabled=ref(true),rotationPaused=ref(false);
const availability=ref({}),availabilityLoading=ref(false),availabilityError=ref('');let generation=0,availabilityGeneration=0,rotationTimer;
const section=computed(()=>({ 'school-services':'schools','for-schools':'schools','our-impact':'impact','explore-our-growth':'growth','support-team':'team','for-families':'services' }[route.params.section]||String(route.params.section||'')));
const settings=computed(()=>data.value?.settings||{}),schools=computed(()=>data.value?.districts.flatMap(d=>d.schools)||[]);
const path=slug=>`/p/itsco${slug?'/'+slug:''}`,asset=name=>`/assets/itsco/${name}`;
const nav=[['Services','services'],['Our Providers','providers'],['For Schools','schools'],['About','about'],['Resources','resources'],['Contact','contact']];
const heroes={
 '':['Support today. Brighter tomorrows.','Therapy That Meets You Where You Are','Compassionate mental health care for children, teens, adults, and families — in our offices, online, and in schools.','counseling-hero.png'],
 providers:['Our providers','Real People. A Brighter Tomorrow.','Find support by school, specialty, insurance, and current availability.','mountains.png'],
 schools:['School-based services','Stronger Students. Healthier Communities.','We partner with school communities to bring mental health support closer to students and families.','counseling-hero.png','Explore our school partners','#school-partners'],
 about:['About ITSCO','Built in Schools. Growing for Communities.','Support for children, teens, adults, and families — brighter tomorrows, together.','students-hero.png','Meet our team','/p/itsco/team'],
 growth:['Explore our growth','From a Shared Vision to a Brighter Tomorrow.','Growing our connections with schools, families, and communities.','students-hero.png','See our impact','/p/itsco/impact'],
 impact:['Our impact','Stronger Students. Healthier Communities.','Real people. Real connections. A brighter tomorrow.','students-hero.png','Explore our growth','/p/itsco/growth'],
 team:['Our team','The People Behind the Progress.','Dedicated professionals. A shared purpose. Support for the clinicians, schools, and families who make up our community.','students-hero.png','Join our team','/careers/itsco'],
 services:['Our services','Support for Every Chapter.','Find a provider who understands your needs, whether you’re looking for yourself, your child, or your family.','counseling-hero.png'],
 insurance:['Insurance & care','A Clearer Path to Support.','Explore provider insurance information and connect with our team about your next steps.','counseling-hero.png'],
 contact:['We’re here to help','Let’s Find Your Next Step.','Questions about care, schools, insurance, or joining our team? Send us a message below.','counseling-hero.png'],
 resources:['Resources','A Little Guidance. A Stronger Start.','Find the right place to get started, connect with your care team, or explore school support.','students-hero.png']};
const hero=computed(()=>{const h=heroes[section.value];if(!h)return null;const content=!section.value?(data.value?.content||{}):{};return {eyebrow:h[0],title:content.heroTitle||h[1],body:content.heroSubtitle||h[2],imageUrl:content.heroImageUrl,image:h[3],cta:h[4],ctaHref:h[5]};});
const services=[{icon:'leaf',title:'Individual Therapy',body:'Space to work through life’s challenges and build on your strengths.',image:'teen-counseling.png'},{icon:'people',title:'Child & Teen Therapy',body:'Support for young people as they grow, learn, and connect.',image:'student-learning.png'},{icon:'people',title:'Family Therapy',body:'Stronger communication and support for your family’s next chapter.',image:'students-hero.png'},{icon:'heart',title:'Couples Therapy',body:'Work toward greater understanding and connection.',image:'counseling-hero.png'},{icon:'screen',title:'Telehealth',body:'Explore virtual options with our providers.',image:'teen-counseling.png'},{icon:'school',title:'School-Based Therapy',body:'Bringing mental health support directly to school communities.',image:'students-hero.png',school:true}];
const why=[['pin','Flexible care options','In office, online, or at school — find care that fits your life.'],['heart','Child & family support','Care built around your family’s needs and strengths.'],['school','School collaboration','Working with families and school teams to support students.'],['shield','Insurance guidance','Find provider insurance information and help with next steps.']];
const principles=[['people','People at the center','Guided by the needs of clients and the people who care for them.'],['school','Care where students are','Connecting mental health support with everyday school life.'],['leaf','Room to grow','Relationships that create space for learning and possibility.'],['chart','Growing together','Building connections while staying close to our purpose.']];
const values=[['shield','Good judgment','Do what’s right.'],['chat','Communication','Listen. Share. Build trust.'],['target','Impact','Create meaningful change.'],['leaf','Curiosity','Keep learning. Stay open.'],['chart','Innovation','Find better ways.'],['heart','Honesty','Be real. Be transparent.'],['people','Selflessness','Put people first.']];
const milestones=computed(()=>Array.isArray(settings.value.milestones)&&settings.value.milestones.length?settings.value.milestones:[{title:'A shared purpose',body:'Support students and families where they are.'},{title:'School connections',body:'Build relationships with school communities.'},{title:'A wider circle of care',body:'Connect people with providers and resources.'},{title:'Brighter tomorrows',body:'Keep listening, learning, and growing together.'}]);
const metrics=computed(()=>data.value?[...(data.value.metrics.studentsSupported!==null?[{icon:'people',label:'Students connected',value:data.value.metrics.studentsSupported}]:[]),{icon:'school',label:'School partners',value:data.value.metrics.schools},{icon:'pin',label:'School districts',value:data.value.metrics.districts},{icon:'heart',label:'Providers & team',value:data.value.metrics.teamMembers}]:[]);
const impactAreas=[['Students','A place to feel supported and build skills for everyday life.','student-learning.png'],['Schools','Connections between school communities and mental health support.','students-hero.png'],['Families','Help navigating care and building a stronger support network.','counseling-hero.png'],['Communities','Relationships that bring people and resources together.','teen-counseling.png']];
const resources=[['Client portal','Already connected with ITSCO? Sign in to your care portal.','/itsco/login'],['School enrollment','Find your school and explore the referral process.','/itsco/school-referral'],['Find your provider','Learn about our team and explore current openings.','/p/itsco/providers']];
const featured=computed(()=>{const p=data.value?.providers||[];return p.length?Array.from({length:Math.min(3,p.length)},(_,i)=>p[(offset.value+i)%p.length]):[];});
const departments=computed(()=>[...new Set((data.value?.team||[]).map(p=>p.department).filter(Boolean))].sort());
const visibleTeam=computed(()=>(data.value?.team||[]).filter(p=>!department.value||p.department===department.value));
function initials(name){return name.split(' ').map(s=>s[0]).slice(0,2).join('');}
async function load(){loading.value=true;await refreshData();loading.value=false;}
async function refreshData(){const id=++generation;error.value='';try{const res=await api.get('/public/marketing-pages/itsco/website-data',{skipAuthRedirect:true});if(id!==generation)return;data.value=res.data;loadAvailability();}catch(e){if(id===generation)error.value=e.response?.status===404?'ITSCO’s website is not published yet. The client portal is still available.':'We couldn’t load the directory. Please try again.';}}
async function loadAvailability(){const id=++availabilityGeneration;availability.value={};availabilityError.value='';if(section.value!=='providers'||!data.value?.agency.schedulingEnabled||!data.value.providers.some(p=>p.onlineScheduling))return;availabilityLoading.value=true;try{const results=await Promise.allSettled(['IN_PERSON','VIRTUAL'].map(programType=>api.get('/public/agency-services/itsco/counselors',{params:{programType},skipAuthRedirect:true})));if(id!==availabilityGeneration)return;const map={};for(const r of results){if(r.status==='rejected'){availabilityError.value='Some online appointment times could not be checked.';continue;}for(const p of r.value.data.providers||[]){const key=p.id||p.providerId;const at=p.availability?.nextAvailableAt;map[key]??={};map[key].hasPublishedOpenings=Boolean(map[key].hasPublishedOpenings||p.availability?.hasPublishedOpenings||at);if(at&&(!map[key]?.nextAvailableAt||at<map[key].nextAvailableAt))map[key].nextAvailableAt=at;}}availability.value=map;}catch{if(id===availabilityGeneration)availabilityError.value='Online appointment times could not be checked.';}finally{if(id===availabilityGeneration)availabilityLoading.value=false;}}
watch(()=>route.fullPath,()=>{menu.value=false;});
watch(section,(value,previous)=>{if(value==='providers'&&previous!=='providers'&&data.value)loadAvailability();});
onMounted(()=>{load();rotationEnabled.value=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;rotationTimer=setInterval(()=>{if(rotationEnabled.value&&!rotationPaused.value&&!document.hidden&&data.value?.providers.length>3)offset.value=(offset.value+3)%data.value.providers.length;},10000);});
onUnmounted(()=>{generation++;availabilityGeneration++;clearInterval(rotationTimer);});
</script>
<style src="../../styles/itsco-public.css"></style>
